import {readOnlyProvider} from './wallet-provider.js';
import {portfolioSummary,holdingsCSV,guestHoldingsRequest,GUEST_HOLDINGS_KEY} from './portfolio.js';
import {wordlist} from '@scure/bip39/wordlists/english.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let refreshSequence=0;
let hooks={},me=null,caps=null,view='community',channel='',search='',threadId='',replyParent='',provider=null,loaded={},busy=false,prices={},walletRead=null;
const channels=['Alpha','Confirmed','Testnet','Retroactive','Scam Watch','Pemula'];
const views=[['community','Komunitas'],['scam','Scam Watch'],['leaderboard','Leaderboard'],['inbox','Notifikasi'],['wallet','Wallet & alat'],['holdings','Aset & klaim'],['assistant','Asisten riset'],['account','Akun & privasi']];
export const platformAccount=()=>me;
export function configurePlatform(options){hooks=options;refreshAccount();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});setInterval(()=>{if(me&&document.visibilityState==='visible'&&!document.activeElement?.closest('form')&&!document.querySelector('dialog[open]')&&document.querySelector('#platform-content')&&['community','thread','inbox'].includes(view)&&!(view==='community'&&loaded.posts?.length>30))refresh(false)},30000)}
async function req(path,body,method){if(!me&&['/holdings','/holdings/archive'].includes(path))return guestHoldingsRequest(localStorage,path,body,method||(body===undefined?'GET':'POST'));const headers={};const init=window.Telegram?.WebApp?.initData;if(init)headers['X-Telegram-Init-Data']=init;const options={headers,credentials:'same-origin'};if(body!==undefined){options.method=method||'POST';headers['Content-Type']='application/json';options.body=JSON.stringify(body)}const r=await fetch('/api/platform'+path,options),data=await r.json();if(!r.ok)throw Error(data.error||'SERVICE_UNAVAILABLE');return data}
async function refreshAccount(){try{caps=await req('/capabilities');me=await req('/me')}catch{me=null}hooks.onAuth?.(me);if(document.querySelector('#platform-content'))refresh()}
function feedback(text){hooks.toast?.(text)}
function protect(text){const words=text.toLowerCase().replace(/[^a-z ]/g,' ').split(/\s+/),dict=new Set(wordlist);let n=0;for(const w of words){n=dict.has(w)?n+1:0;if(n>=12)throw Error('Kemungkinan seed phrase. Konten tidak dikirim.')}if(/(?:private[ _-]?key|seed[ _-]?phrase|mnemonic)\s*[:=]\s*\S{10,}/i.test(text)||/(?:^|\s)(?:0x)?[a-fA-F0-9]{64}(?:$|\s)/.test(text))throw Error('Kemungkinan data rahasia. Konten tidak dikirim.')}
export function platformPage(mode){if(mode)view=mode;setTimeout(()=>refresh(),0);return `<section class="platform-intro"><div><span class="eyeline">AIRDROP MUSEUM / HUNTER NETWORK</span><h1>Riset bertemu komunitas.</h1><p>Diskusi berbasis sumber, identitas yang Anda kendalikan, dan alat untuk pekerjaan Web3.</p></div><button class="${me?'secondary':'primary'}" data-platform-view="account">${me?h(me.username):'Masuk / buat akun'}</button></section><div class="platform-tabs">${views.map(([id,label])=>`<button data-platform-view="${id}" class="${view===id?'active':''}">${label}</button>`).join('')}${me?.moderator?'<button data-platform-view="moderation">Moderator</button>':''}</div><section id="platform-content" aria-live="polite"><div class="platform-loading">Memuat ruang Museum…</div></section>`}
function loginWall(){return `<div class="platform-empty"><span class="platform-seal">◈</span><h2>Identitas untuk kontribusi nyata.</h2><p>Masuk untuk menulis, menyimpan diskusi, mengelola aset atau menerima notifikasi pribadi. Membaca kanal publik tetap terbuka.</p><button class="primary" data-platform-view="account">Buka akun</button></div>`}
function errorPanel(e){return `<div class="platform-error"><b>Layanan belum dapat dimuat</b><p>${h(e.message)}</p><button class="secondary" data-platform-refresh>Ulangi</button></div>`}
async function refresh(showLoading=true){const target=document.querySelector('#platform-content');if(!target)return;if(showLoading)target.innerHTML='<div class="platform-loading">Memuat…</div>';document.querySelectorAll('[data-platform-view]').forEach(b=>b.classList.toggle('active',b.dataset.platformView===view));const requested=view,requestNumber=++refreshSequence;try{let html='';if(!caps)try{caps=await req('/capabilities')}catch{}
if(view==='account'){if(me)loaded.sessions=(await req('/sessions')).sessions;html=accountUI();}else if(view==='wallet')html=await walletUI();else if(view==='community'){const data=await req('/posts?channel='+encodeURIComponent(channel)+'&q='+encodeURIComponent(search));loaded.posts=data.posts;html=feedUI(data)}else if(view==='thread'){const data=await req('/thread?id='+encodeURIComponent(threadId));loaded.thread=data;html=threadUI(data)}else if(view==='scam'){const data=await req('/scam-watch');html=scamUI(data)}else if(view==='leaderboard'){const data=await req('/leaderboard?kind='+(loaded.rankKind||'contributors'));html=leaderboardUI(data)}else if(view==='holdings'){const data=await req('/holdings');loaded.holdings=data.holdings;html=holdingsUI(data)}else if(!me)html=loginWall();else if(view==='bookmarks'){const data=await req('/bookmarks');html=`<div class="platform-heading"><h2>Diskusi tersimpan</h2><button class="text-btn" data-platform-view="community">Kembali ke feed</button></div>`+(data.posts.length?data.posts.map(p=>`<article class="saved-thread"><button class="saved-thread-open" data-thread="${h(p.id)}"><span>${h(p.channel)}</span><b>${h(p.title)}</b><small>${h(p.created_at)}</small></button><button class="text-btn" data-unbookmark="${h(p.id)}">Lepas bookmark</button></article>`).join(''):'<div class="platform-empty"><h3>Belum ada diskusi tersimpan.</h3><p>Simpan kontribusi dari feed untuk dibaca kembali.</p></div>')}else if(view==='inbox'){const [data,prefs]=await Promise.all([req('/notifications'),req('/preferences')]);html=inboxUI(data,prefs)}else if(view==='holdings'){const data=await req('/holdings');loaded.holdings=data.holdings;html=holdingsUI(data)}else if(view==='assistant')html=assistantUI();else if(view==='moderation'){const data=await req('/moderation');html=moderationUI(data)}if(requested===view&&requestNumber===refreshSequence&&target.isConnected){target.innerHTML=html;restoreDraft(target.querySelector('[data-draft]'))}}catch(e){if(requested===view&&requestNumber===refreshSequence)target.innerHTML=errorPanel(e)}}
function accountUI(){if(!me)return `<div class="account-layout"><section class="platform-panel account-primary"><span class="eyeline">READ-ONLY WALLET</span><h2>Wallet Anda.<br>Ruang Anda.</h2><p>Hubungkan MetaMask, Rabby, atau WalletConnect untuk membaca alamat publik. Masuk ke akun melalui Telegram atau email; wallet tidak diminta menandatangani pesan.</p><button class="primary" data-wallet-login>Hubungkan wallet read-only</button><button class="secondary" data-walletconnect ${!caps?.walletConnect?'disabled':''}>WalletConnect ${caps?.walletConnect?'':'· perlu Project ID'}</button><div class="account-note">Privasi aktif secara bawaan. Wallet dan aktivitas on-chain tidak ditampilkan pada profil publik.</div></section><section class="platform-panel"><span class="eyeline">EMAIL ALTERNATIVE</span>${window.Telegram?.WebApp?.initData?'<button class="primary" data-telegram-session>Aktifkan sesi Telegram</button>':''}<h2>Masuk melalui email</h2><form id="email-start"><label>Email<input name="email" type="email" required></label><button class="secondary" ${!caps?.email?'disabled':''}>Kirim kode login</button></form><form id="email-verify"><input name="id" type="hidden" value="${h(loaded.emailId||'')}"><label>Kode enam digit<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><button class="primary" ${!loaded.emailId?'disabled':''}>Verifikasi kode</button></form><p class="connection">${caps?.email?'Kode kedaluwarsa setelah 10 menit.':'Pengiriman email memerlukan konfigurasi domain pengirim dan penyedia email.'}</p></section></div>`;
return `<div class="account-layout"><section class="platform-panel"><span class="eyeline">YOUR SERVER PROFILE</span><h2>${h(me.avatar)} ${h(me.username)}</h2><p class="account-wallet">${h(me.wallet||me.email||me.id)}</p><div class="network-kpis"><span><b>${me.reputation}</b>Reputasi server</span><span><b>${me.private?'Privat':'Publik'}</b>Visibilitas</span></div><form id="server-profile"><label>Username<input name="username" value="${h(me.username)}" minlength="3" maxlength="40" required></label><label>Avatar<select name="avatar">${['◈','◎','✧','△','✦','⬡'].map(v=>`<option ${v===me.avatar?'selected':''}>${v}</option>`).join('')}</select></label><label>Chain favorit · pisahkan koma<input name="chains" value="${h(me.chains.join(', '))}" maxlength="240"></label><label class="check-label"><input type="checkbox" name="private" ${me.private?'checked':''}> Sembunyikan wallet dan aktivitas dari publik</label><button class="primary">Simpan profil server</button></form></section><section class="platform-panel"><span class="eyeline">SESSION & PRIVACY</span><h2>Anda menentukan yang dibagikan.</h2>${window.Telegram?.WebApp?.initData?'<button class="secondary" data-telegram-session>Aktifkan sesi Telegram</button><p class="connection">Aktifkan sesi sebelum membuka konsol admin.</p>':''}<p>Profil publik hanya memuat nama, avatar, kontribusi dan reputasi. Wallet tidak disertakan dalam feed diskusi. Leaderboard mengabaikan profil privat.</p><p>Posting dan komentar yang Anda kirim tetap merupakan konten publik. Catatan riset lokal hanya diunggah melalui tombol sinkronisasi.</p><button class="secondary" data-platform-view="inbox">Preferensi notifikasi</button>${sessionsUI()}<button class="danger-button" data-wallet-logout>Keluar dari sesi server</button><p class="connection">Sesi menggunakan cookie HttpOnly dan berakhir dalam tujuh hari. Jangan berbagi seed phrase atau private key.</p></section></div>`}
function feedUI(data){return `<div class="community-command"><div><span class="eyeline">OPEN DISCUSSION / EVIDENCE FIRST</span><h2>Temukan sudut pandang baru.</h2><p>Bagikan sumber, tanyakan konteks, dan dokumentasikan pembelajaran.</p></div><div><button class="secondary" data-platform-view="bookmarks">Tersimpan</button><button class="primary" data-new-post>${me?'Tulis kontribusi':'Masuk untuk menulis'}</button></div></div><div class="community-channels"><button data-channel="" class="${!channel?'active':''}">Semua kanal</button>${channels.map(c=>`<button data-channel="${c}" class="${channel===c?'active':''}">${c}</button>`).join('')}</div><form id="feed-search" class="feed-search"><input name="q" type="search" placeholder="Cari diskusi, panduan, atau temuan…" value="${h(search)}" maxlength="80"><button class="secondary">Cari</button></form><div class="community-layout"><div>${data.posts.length?data.posts.map(postCard).join(''):`<div class="platform-empty"><span class="platform-seal">✧</span><h3>Mulai diskusi yang berguna.</h3><p>Belum ada kontribusi pada pilihan kanal ini. Tulis berdasarkan sumber yang dapat ditinjau.</p></div>`}${data.next?`<button class="secondary" data-feed-next="${h(data.next)}">Muat kontribusi berikutnya</button>`:''}</div><aside class="community-sidebar"><span class="eyeline">COMMUNITY STANDARD</span><h3>Konteks sebelum kesimpulan.</h3><ol><li>Sertakan sumber dan batas informasi.</li><li>Bedakan rumor dari pengumuman resmi.</li><li>Jangan bagikan rahasia wallet.</li><li>Laporan memerlukan bukti dan moderasi.</li></ol><div class="sidebar-feature"><b>Reputasi diperoleh dari kontribusi.</b><p>Voting tidak otomatis menghasilkan reputasi. Panduan berguna dan laporan terverifikasi dinilai moderator.</p></div><button class="text-btn" data-platform-view="scam">Buka Scam Watch →</button></aside></div>`}
function postCard(p){return `<article class="network-post"><div class="post-identity"><span>${h(p.avatar)}</span><div><b>${h(p.username)}</b><small>${p.reputation||0} reputasi${p.reputation>=100?' · Kontributor diakui':''} · ${h(p.created_at)}</small></div><em>${h(p.channel)}</em></div>${p.live?'<span class="live-thread-label">● Live thread · diperbarui berkala</span>':''}<button class="network-post-title" data-thread="${h(p.id)}">${h(p.title)}</button><p>${h(p.body.slice(0,350))}${p.body.length>350?'…':''}</p><div class="post-tags">${p.tags.map(t=>`<span>#${h(t)}</span>`).join('')}${p.chain?`<span>${h(p.chain)}</span>`:''}${p.project_id?`<span>Proyek: ${h(p.project_id)}</span>`:''}</div><div class="post-actions"><button data-vote="${h(p.id)}" data-value="1" aria-label="Upvote">↑</button><b>${p.score||0}</b><button data-vote="${h(p.id)}" data-value="-1" aria-label="Downvote">↓</button><button data-vote="${h(p.id)}" data-value="0">Reset vote</button><button data-thread="${h(p.id)}">${p.comments||0} komentar</button><button data-bookmark="${h(p.id)}">Simpan</button><button data-share-post="${h(p.id)}">Bagikan</button><button data-report-target="${h(p.id)}" data-report-type="post">Laporkan</button></div></article>`}
function compose(){if(!me){view='account';refresh();return}dialog(`<span class="eyeline">CONTRIBUTION / PUBLIC</span><h2>Tambahkan konteks ke komunitas.</h2><form id="create-post" data-draft="post"><label>Judul<input name="title" maxlength="140" minlength="5" required></label><div class="form-grid"><label>Kanal<select name="channel">${channels.map(c=>`<option>${c}</option>`).join('')}</select></label><label>Chain<input name="chain" maxlength="30"></label></div><label>ID proyek · opsional<input name="projectId" maxlength="80"></label><label>Tag · pisahkan koma<input name="tags" maxlength="120"></label><label>Isi kontribusi<textarea name="body" minlength="20" maxlength="6000" rows="7" required placeholder="Sumber, temuan, ketidakpastian, dan langkah selanjutnya…"></textarea></label><label class="check-label"><input type="checkbox" name="live"> Jadikan live thread diskusi</label><p class="connection">Konten dipublikasikan. Deteksi rahasia bekerja di perangkat dan server; tetap periksa sebelum mengirim.</p><div class="draft-toolbar"><span id="draft-status">Draft tersimpan di perangkat ini saat Anda mengetik.</span><button type="button" class="text-btn" data-clear-draft>Hapus draft</button></div><button class="primary">Terbitkan kontribusi</button></form>`)}
function threadUI(data){const known=new Set(data.comments.map(c=>c.id)),ordered=[];function append(parent,depth){for(const c of data.comments.filter(c=>(c.parent_id&&known.has(c.parent_id)?c.parent_id:null)===parent)){ordered.push({...c,depth});if(depth<6)append(c.id,depth+1)}}append(null,0);data.comments=ordered;const p=data.post;return `<button class="text-btn" data-platform-view="community">← Kembali ke komunitas</button><article class="thread-article"><span class="eyeline">${h(p.channel)} / ${p.live?'LIVE THREAD':'DISCUSSION'}</span><h1>${h(p.title)}</h1><div class="post-identity"><span>${h(p.avatar)}</span><div><b>${h(p.username)}</b><small>${h(p.created_at)}</small></div></div><p class="thread-body">${h(p.body)}</p><div class="post-actions"><button data-vote="${h(p.id)}" data-value="1">↑ Upvote</button><button data-vote="${h(p.id)}" data-value="-1">↓ Downvote</button><button data-bookmark="${h(p.id)}">Simpan</button><button data-share-post="${h(p.id)}">Bagikan</button><button data-report-target="${h(p.id)}" data-report-type="post">Laporkan</button></div></article><div class="platform-heading"><h2>${data.comments.length} komentar</h2><small>Balasan dan mention diperbarui setiap 30 detik saat terbuka.</small></div><div class="comment-thread">${data.comments.map(c=>`<article class="network-comment" style="--depth:${c.depth}"><div class="post-identity"><span>${h(c.avatar)}</span><div><b>${h(c.username)}</b><small>${h(c.created_at)}${c.parent_id?' · balasan':''}</small></div></div><p>${h(c.body)}</p><div class="post-actions"><button data-reply="${h(c.id)}">Balas</button><button data-vote="${h(c.id)}" data-vote-type="comment" data-value="1">↑ ${c.score}</button><button data-vote="${h(c.id)}" data-vote-type="comment" data-value="-1">↓</button><button data-report-target="${h(c.id)}" data-report-type="comment">Laporkan</button></div></article>`).join('')}</div>${me?`<form id="create-comment" data-draft="comment" class="platform-panel"><label>${replyParent?'Balas komentar terpilih':'Tambahkan komentar'}<textarea name="body" rows="3" minlength="3" maxlength="2000" required></textarea></label>${replyParent?'<button type="button" class="text-btn" data-reply="">Batalkan balasan</button>':''}<small id="draft-status">Draft komentar lokal</small><button class="primary">Kirim komentar publik</button></form>`:loginWall()}`}
function scamUI(data){return `<div class="community-command"><div><span class="eyeline">SCAM WATCH / REVIEWED REPORTS</span><h2>Sinyal yang perlu ditinjau.</h2><p>Hanya laporan yang ditinjau moderator tampil di sini. Laporan belum ditinjau tidak menjadi tuduhan publik otomatis.</p></div><button class="primary" data-report-target="" data-report-type="domain">Buat laporan</button></div>${data.reports.length?data.reports.map(r=>`<article class="platform-panel"><span class="source-badge">Ditinjau moderator</span><h3>${h(r.target_id)}</h3><p>${h(r.reason)}</p><code>${h(r.evidence)}</code><blockquote>${h(r.resolution)}</blockquote></article>`).join(''):'<div class="platform-empty"><span class="platform-seal">⬡</span><h3>Belum ada laporan terverifikasi.</h3><p>Informasi kosong tidak membuktikan bahwa suatu domain aman.</p></div>'}`}
function reportDialog(target,type){if(!me){view='account';refresh();return}dialog(`<span class="eyeline">EVIDENCE / PRIVATE REPORT</span><h2>Laporkan untuk ditinjau.</h2><form id="create-report"><label>Jenis target<select name="type">${['domain','project','post','comment'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><label>Target<input name="target" value="${h(target)}" maxlength="500" required></label><label>Alasan & konteks<textarea name="reason" rows="4" minlength="20" maxlength="1000" required></textarea></label><label>URL bukti HTTPS<input name="evidence" type="url" required maxlength="500"></label><p class="connection">Laporan masuk antrean moderator. Jangan lampirkan rahasia, data korban, atau klaim tanpa bukti.</p><button class="primary">Kirim laporan</button></form>`)}
function leaderboardUI(data){return `<div class="platform-heading"><div><span class="eyeline">REPUTATION / SERVER RECORDS</span><h2>Kontribusi yang tercatat.</h2></div><select id="rank-kind"><option value="contributors" ${data.kind==='contributors'?'selected':''}>Kontributor berguna</option><option value="hunters" ${data.kind==='hunters'?'selected':''}>Hunter konsisten</option><option value="scam" ${data.kind==='scam'?'selected':''}>Analis laporan</option></select></div><div class="leaderboard-list">${data.users.length?data.users.map((u,i)=>`<article><b class="rank-number">${i+1}</b><span class="rank-avatar">${h(u.avatar)}</span><div><h3>${h(u.username)}</h3><p>${u.quests} quest · ${u.activeDays} hari aktif terverifikasi · ${u.reports} laporan ditinjau</p></div><strong>${u.reputation}<small>REPUTASI</small></strong></article>`).join(''):'<div class="platform-empty"><h3>Belum ada peringkat publik.</h3><p>Profil privat tidak ditampilkan. XP lokal tidak digunakan sebagai reputasi komunitas.</p></div>'}</div>`}
function inboxUI(data,p){return `<div class="platform-heading"><div><span class="eyeline">PRIVATE INBOX / SERVER</span><h2>Pembaruan untuk Anda.</h2></div><button class="text-btn" data-read-notifications>Tandai semua dibaca</button></div><div class="inbox-layout"><section>${data.notifications.length?data.notifications.map(n=>`<article class="inbox-item ${n.read_at?'read':''}"><span class="inbox-dot"></span><div><small>${h(n.type)} · ${h(n.created_at)}</small><h3>${h(n.payload.title||n.payload.status||'Pembaruan Museum')}</h3>${n.payload.postId?`<button class="text-btn" data-thread="${h(n.payload.postId)}">Buka diskusi →</button>`:''}<button class="text-btn" data-notification-read="${h(n.id)}">${n.read_at?'Sudah dibaca':'Tandai dibaca'}</button></div></article>`).join(''):'<div class="platform-empty"><h3>Belum ada pembaruan.</h3><p>Balasan, mention, hasil moderasi, dan tanggal dari data cloud akan muncul di sini.</p></div>'}</section><section class="platform-panel"><h3>Saluran pengingat</h3><form id="delivery-preferences"><label class="check-label"><input type="checkbox" name="email" ${p.email?'checked':''} ${!caps.email||!me.email?'disabled':''}> Email terverifikasi</label><label class="check-label"><input type="checkbox" name="telegram" ${p.telegram?'checked':''} ${!caps.telegram||!me.id.startsWith('tg:')?'disabled':''}> Chat bot Telegram akun ini</label><label class="check-label"><input type="checkbox" name="discord" ${p.discord?'checked':''}> Webhook Discord milik Anda</label><label>Webhook Discord<input type="password" name="discordWebhook" placeholder="Masukkan kembali untuk menyimpan" autocomplete="off" maxlength="500"></label><p class="connection">Webhook tidak ditampilkan kembali. Saluran hanya menerima kiriman setelah Anda mengaktifkannya. Pengiriman terjadwal setiap jam, bukan jaminan waktu tepat.</p><button class="primary">Simpan preferensi</button></form><button class="secondary" data-enable-push ${!caps.push?'disabled':''}>${caps.push?'Aktifkan push browser':'Push · perlu kunci VAPID'}</button><p class="connection">Radar tanggal tetap tersedia secara lokal. Server hanya memproses tanggal yang sudah disinkronkan.</p></section></div>`}
function holdingsUI(data){const summary=portfolioSummary(data.holdings,prices),rows=data.holdings.filter(r=>!!r.archived===!!loaded.showArchived);return `${!me?'<div class="guest-workbench"><b>Ledger perangkat · dapat digunakan tanpa login</b><p>Catatan aset disimpan di browser ini. Ekspor CSV untuk cadangan. Login membuka ledger akun yang terpisah; data perangkat tidak diunggah otomatis.</p><button class="text-btn" data-platform-view="account">Buka akun →</button></div>':''}<div class="platform-heading"><div><span class="eyeline">PROFILE / TOKEN WORKBENCH</span><h2>Aset, klaim & hasil.</h2></div><div class="workbench-actions"><button class="secondary" data-export-holdings>Ekspor CSV</button><button class="primary" data-add-holding>Catat token</button></div></div><div class="network-kpis"><span><b>${summary.claimed}</b>Aset sudah diklaim</span><span><b>$${summary.value.toFixed(2)}</b>Subtotal aset dengan harga</span><span><b>${summary.net===null?'Belum lengkap':'$'+summary.net.toFixed(2)}</b>Selisih terhadap biaya tercatat</span></div><div class="portfolio-quality"><span>${summary.waiting} catatan belum diklaim</span><span>${summary.vesting} catatan vesting</span><span>${summary.unknown} aset diklaim tanpa harga</span></div><p class="connection">Hanya status diklaim yang masuk subtotal. Aset menunggu klaim dan vesting dipisahkan. Tanpa harga lengkap, selisih tidak ditampilkan sebagai keuntungan. Ledger manual ini bukan saldo wallet atau laporan pajak.</p><div class="holdings-controls"><button class="secondary" data-refresh-prices ${!me?'disabled':''}>${me?'Ambil harga CoinGecko':'Harga pasar · masuk dahulu'}</button><button class="secondary" data-toggle-archived>${loaded.showArchived?'Tampilkan aset aktif':'Lihat arsip'}</button><span>${loaded.priceAt?'Harga diminta '+h(new Date(loaded.priceAt).toLocaleString('id-ID')):'Harga manual sampai diperbarui'}</span></div><div class="holdings-table">${rows.length?rows.map(r=>{const price=prices[r.price_id]?.usd??r.manual_price;return `<article class="holding-record ${r.archived?'archived-record':''}"><span class="token-symbol">${h(r.symbol.slice(0,2))}</span><div><h3>${h(r.symbol)}</h3><p>${h(r.chain)} · ${h(r.claim_status)} · ${h(r.received_at||'Tanggal belum dicatat')}</p><small>Revisi ${r.revision}${r.updated_at?' · diperbarui '+h(r.updated_at):''}</small></div><div><b>${r.amount.toLocaleString('id-ID')}</b><small>${price==null?'Harga belum tersedia':'$'+(r.amount*price).toFixed(2)}${r.claim_status!=='claimed'?' · belum masuk subtotal':''}</small></div><span class="source-badge">${prices[r.price_id]?'CoinGecko':'Manual'}</span><div class="holding-row-actions"><button class="text-btn" data-edit-holding="${h(r.id)}">Edit catatan</button><button class="text-btn" data-archive-holding="${h(r.id)}">${r.archived?'Pulihkan':'Arsipkan'}</button></div></article>`}).join(''):`<div class="platform-empty"><h3>${loaded.showArchived?'Arsip masih kosong.':'Mulai catat hasil partisipasi.'}</h3><p>${loaded.showArchived?'Catatan yang diarsipkan dapat dipulihkan kapan saja.':'Pisahkan token yang menunggu klaim, vesting, dan yang sudah diterima.'}</p></div>`}</div>`}
function holdingDialog(row){const r=row||{};dialog(`<span class="eyeline">PERSONAL TOKEN RECORD / ${row?'EDIT':'NEW'}</span><h2>${row?'Perbaiki catatan aset.':'Catat aset airdrop.'}</h2><form id="holding-form" data-holding="${h(r.id||'')}" data-revision="${r.revision||0}"><div class="form-grid"><label>Simbol<input name="symbol" maxlength="20" value="${h(r.symbol||'')}" required></label><label>Chain<input name="chain" maxlength="40" value="${h(r.chain||'')}" required></label><label>Jumlah<input name="amount" type="number" min="0.000000000000000001" step="any" value="${r.amount??''}" required></label><label>Biaya tercatat USD<input name="cost" type="number" min="0" step="any" value="${r.cost??0}"></label><label>Harga manual USD<input name="manualPrice" type="number" min="0" step="any" value="${r.manual_price??''}" placeholder="Opsional"></label><label>CoinGecko ID<input name="priceId" pattern="[a-z0-9-]+" value="${h(r.price_id||'')}" placeholder="ethereum"></label><label>Status klaim<select name="claimStatus">${[['pending','Menunggu'],['eligible','Eligible · catatan pribadi'],['claimed','Diklaim · catatan pribadi'],['vesting','Vesting']].map(([key,label])=>`<option value="${key}" ${key===(r.claim_status||'pending')?'selected':''}>${label}</option>`).join('')}</select></label><label>Tanggal diterima<input name="receivedAt" type="date" value="${h(r.received_at||'')}"></label></div><label>Kontrak / mint · catatan<input name="contract" maxlength="100" value="${h(r.contract||'')}"></label><p class="connection">Perubahan diperiksa agar catatan versi lama tidak menimpa versi terbaru.</p><button class="primary">${row?'Simpan perubahan':'Simpan catatan aset'}</button></form>`)}
async function walletUI(){const quests=await req('/quests');loaded.quests=quests.quests;return `<div class="wallet-tool-grid"><section class="platform-panel"><span class="eyeline">READ ONLY / CONNECTED PROVIDER</span><h2>Wallet observation desk.</h2><p>Baca saldo native dan jumlah transaksi dari provider wallet Anda. Data ini tidak membuktikan kualifikasi airdrop.</p><button class="primary" data-read-wallet>Baca wallet</button>${walletRead?`<div class="wallet-readout"><code>${h(walletRead.address)}</code><b>Chain ${walletRead.chain}</b><span>${walletRead.balance} native unit · ${walletRead.nonce} transaksi keluar</span></div>`:''}<h3>On-chain quests</h3>${quests.quests.length?quests.quests.map(q=>`<article class="quest-proof"><b>${h(q.title)}</b><p>Chain ${q.chain} · ${q.points} reputasi · target ${h(q.target)}</p><form data-quest-proof="${h(q.id)}"><label>Hash transaksi<input name="txHash" pattern="0x[a-fA-F0-9]{64}" required></label><button class="secondary">Verifikasi di server</button></form></article>`).join(''):'<p class="connection">Belum ada quest yang diterbitkan moderator. Tidak ada aktivitas berbayar atau reward yang dibuat-buat.</p>'}</section><section class="platform-panel"><span class="eyeline">TRANSACTION PREVIEW / NO BROADCAST</span><h2>Simulasi & approval.</h2><form id="simulate-form"><label>Target kontrak<input name="to" pattern="0x[a-fA-F0-9]{40}" required></label><label>Calldata hex<textarea name="data" rows="3" pattern="0x[a-fA-F0-9]*" placeholder="0x" required></textarea></label><label>Nilai native · hex<input name="value" value="0x0" pattern="0x[a-fA-F0-9]+" required></label><button class="secondary">Jalankan eth_call & estimasi gas</button></form><p class="connection">Simulasi provider pada state terbaru; bukan jaminan keamanan atau keberhasilan transaksi. Museum tidak mengirim transaksi.</p><form id="allowance-form"><label>Kontrak token ERC-20<input name="token" pattern="0x[a-fA-F0-9]{40}" required></label><label>Alamat spender<input name="spender" pattern="0x[a-fA-F0-9]{40}" required></label><button class="secondary">Periksa allowance</button></form><div id="wallet-tool-result" class="tool-result"></div></section><section class="platform-panel"><span class="eyeline">DOMAIN LENS</span><h2>Periksa tujuan.</h2><form id="domain-form"><label>URL HTTPS<input name="url" type="url" required maxlength="500"></label><button class="secondary">Bandingkan domain referensi</button></form><div id="domain-result" class="tool-result"></div><p class="connection">Daftar referensi diisi moderator berdasarkan sumber. Kemiripan domain adalah sinyal untuk diperiksa, bukan putusan otomatis.</p></section></div>`}
function assistantUI(){return `<div class="assistant-layout"><section class="platform-panel"><span class="eyeline">MUSEUM RESEARCH ASSISTANT / AI</span><h2>Urai aturan. Temukan pertanyaan.</h2><p>Tempel ketentuan publik atau potongan kode kontrak untuk diringkas. Asisten membahas syarat, variabel biaya gas, red flag dan konsep kontrak dari materi yang diberikan.</p><form id="assistant-form"><label>Materi publik untuk dianalisis<textarea name="text" rows="10" minlength="20" maxlength="6000" required placeholder="Ketentuan program dan sumber yang Anda tinjau…"></textarea></label><label class="check-label"><input type="checkbox" required> Saya meninjau materi ini dan menyetujui pengiriman ke layanan AI Cloudflare.</label><button class="primary" ${!caps.ai?'disabled':''}>${caps.ai?'Analisis materi · maksimum 3 per hari':'AI belum dikonfigurasi'}</button></form></section><section class="platform-panel assistant-answer"><span class="eyeline">ANALYSIS / NOT VERIFICATION</span><h3>Hasil analisis</h3><div id="assistant-result"><p>Jawaban akan muncul di sini. Model dapat keliru dan tidak melakukan audit, memastikan eligibility, atau menjamin reward.</p></div></section></div>`}
function moderationUI(data){return `<div class="platform-heading"><div><span class="eyeline">AUTHORIZED MODERATOR DESK</span><h2>Review, bukan asumsi.</h2><p><a class="secondary" href="/discovery.html">Discovery — Sumber & Review Queue</a></p></div></div>${data.reports.map(r=>`<article class="platform-panel"><h3>${h(r.target_type)} · ${h(r.target_id)}</h3><p>${h(r.reason)}</p><code>${h(r.evidence)}</code><form data-moderation-report="${h(r.id)}"><label>Keputusan<select name="status"><option value="verified">Terverifikasi</option><option value="rejected">Tidak didukung bukti</option></select></label><label>Dasar keputusan<textarea name="note" minlength="20" maxlength="1000" required></textarea></label><button class="primary">Simpan tinjauan</button></form></article>`).join('')||'<section class="platform-panel"><p>Antrean laporan kosong.</p></section>'}<div class="moderation-tools"><section class="platform-panel"><h3>Moderasi konten</h3><form id="moderate-content"><label>Jenis<select name="type"><option value="post">Post</option><option value="comment">Comment</option></select></label><label>ID konten<input name="id" required></label><label>Status<select name="status"><option value="hidden">Sembunyikan</option><option value="published">Publikasikan kembali</option></select></label><label>Dasar keputusan<textarea name="note" minlength="20" required></textarea></label><button class="secondary">Terapkan</button></form><form id="recognize-guide"><h3>Akui panduan berguna</h3><label>ID post<input name="id" required></label><label>Alasan penilaian<textarea name="note" minlength="20" required></textarea></label><button class="secondary">Berikan 25 reputasi sekali</button></form></section><section class="platform-panel"><h3>Domain referensi</h3><form id="moderate-domain"><label>Hostname<input name="host" required></label><label>ID proyek<input name="projectId"></label><label>URL sumber<input name="source" type="url" required></label><label>Dasar tinjauan<textarea name="note" minlength="20" required></textarea></label><button class="secondary">Catat domain</button></form><h3>Terbitkan quest on-chain</h3><form id="moderate-quest"><label>Judul<input name="title" required></label><label>ID proyek<input name="projectId"></label><label>Chain ID<input name="chain" type="number" required></label><label>Kontrak target<input name="target" pattern="0x[a-fA-F0-9]{40}" required></label><label>Function selector<input name="selector" pattern="0x[a-fA-F0-9]{8}" required></label><label>Poin<input name="points" type="number" min="1" max="100" value="25"></label><button class="secondary">Terbitkan quest</button></form></section><section class="platform-panel"><h3>Direktori bersama</h3><form id="moderate-exhibit"><label>URL pengumuman sumber<input name="source" type="url" required></label><label>JSON proyek · name, chain, tasks, syarat<textarea name="project" rows="8" required placeholder='{"name":"Proyek","chain":"Ethereum","tasks":["Tinjau sumber"]}'></textarea></label><button class="secondary">Terbitkan catatan sumber</button></form><p class="connection">Publikasi direktori bukan endorsement dan tidak membuat sumber dianggap aman.</p></section></div><section class="platform-panel"><h3>Audit moderasi</h3>${data.log.map(l=>`<p><b>${h(l.action)}</b> · ${h(l.created_at)}<br>${h(l.note)}</p>`).join('')||'<p>Belum ada tindakan.</p>'}</section>`}
